import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware to extract user context from JWT (simplified)
function extractUser(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // In production this would verify JWT signature
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
  req.user = payload;
  next();
}

// Search endpoint for internal reporting dashboard
app.get('/api/reports/search', extractUser, async (req, res) => {
  try {
    const { category, date_from, date_to, sort_field, sort_dir } = req.query;

    // Validate sort direction
    const direction = sort_dir === 'DESC' ? 'DESC' : 'ASC';

    // Build query with parameterized values for data filters
    let query = `SELECT r.id, r.title, r.category, r.created_at, r.author_id, r.summary 
                 FROM reports r 
                 WHERE r.org_id = $1`;
    const params = [req.user.org_id];
    let paramIdx = 2;

    if (category) {
      query += ` AND r.category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (date_from) {
      query += ` AND r.created_at >= $${paramIdx}`;
      params.push(date_from);
      paramIdx++;
    }

    if (date_to) {
      query += ` AND r.created_at <= $${paramIdx}`;
      params.push(date_to);
      paramIdx++;
    }

    // Sort field - validated against allowed columns
    const allowedSorts = ['id', 'title', 'category', 'created_at'];
    const sortColumn = allowedSorts.includes(sort_field) ? sort_field : 'created_at';

    query += ` ORDER BY r.${sortColumn} ${direction}`;
    query += ` LIMIT 100`;

    const result = await pool.query(query, params);
    res.json({ reports: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Detail endpoint with dynamic field selection
app.get('/api/reports/:id/export', extractUser, async (req, res) => {
  try {
    const reportId = req.params.id;
    const fields = req.query.fields || 'id,title,summary';

    // User requests specific fields for CSV export
    const requestedFields = fields.split(',').map(f => f.trim());

    // Build SELECT with requested fields
    const selectClause = requestedFields.map(f => `r.${f}`).join(', ');

    const query = `SELECT ${selectClause} FROM reports r WHERE r.id = $1 AND r.org_id = $2`;
    const result = await pool.query(query, [reportId, req.user.org_id]);

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'not found' });
    }

    // Format as CSV
    const row = result.rows[0];
    const csv = Object.keys(row).join(',') + '\n' + Object.values(row).join(',');
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename=report_${reportId}.csv`);
    res.send(csv);
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000, () => {
  console.log(`Report service running on port ${process.env.PORT || 3000}`);
});
